data=json.loads((OUT/'review-data.json').read_text());assets=data['assets'];findings=data['findings']
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyUX',fontName='Helvetica',fontSize=9.3,leading=12.3,spaceAfter=6,textColor=colors.HexColor('#24354A')))
