def footer(c,doc):
 c.saveState();w,h=doc.pagesize;c.setStrokeColor(colors.HexColor('#D6DFE6'));c.line(40,32,w-40,32);c.setFont('Helvetica',7);c.setFillColor(colors.HexColor('#526279'));c.drawString(40,21,'OurApp_vs_Obsidian | Phase 1 expert UX review | Live performance unmeasured');c.drawRightString(w-40,21,str(doc.page));c.restoreState()
class UXDoc(SimpleDocTemplate):
 def afterFlowable(self,item):
  if isinstance(item,Paragraph) and item.style.name=='HeadingUX':
   title=item.getPlainText();key='section-'+str(self.page);self.canv.bookmarkPage(key);self.canv.addOutlineEntry(title,key,level=0,closed=False)
